import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CHeM0PsO.js";const i="/network-overview.svg",A=JSON.parse('{"title":"系统架构","description":"AI实验室当前贵阳—遵义网络架构、链路、VLAN 和策略路由关系。","frontmatter":{"title":"系统架构","description":"AI实验室当前贵阳—遵义网络架构、链路、VLAN 和策略路由关系。"},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1785475798000}'),c={name:"guide/architecture.md"};function d(l,e,n,s,h,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h1><h2 id="当前网络架构" tabindex="-1">当前网络架构 <a class="header-anchor" href="#当前网络架构" aria-label="Permalink to &quot;当前网络架构&quot;">​</a></h2><p><img src="'+i+'" alt="AI实验室网络架构概览"></p><p>文档页展示的是概览图，源文件位于 <code>docs/public/network-overview.mmd</code>；完整的实际拓扑保留在 <code>docs/public/network-architecture.mmd</code>，仅作为配置与排障时的技术参考。</p><h2 id="贵阳网络摘要" tabindex="-1">贵阳网络摘要 <a class="header-anchor" href="#贵阳网络摘要" aria-label="Permalink to &quot;贵阳网络摘要&quot;">​</a></h2><ul><li><strong>边界与出口</strong>：CCR1009（<code>192.168.99.1</code>，RouterOS 7.19.3）承担网关、DHCP、DNS、防火墙和策略路由；三路 PPPoE 为主出口，200M 静态专线（VLAN 214）为备用出口及公网入站。</li><li><strong>交换与无线</strong>：CCR 与 H3C SW1 通过 <code>bond-sw1</code> 的四链路 LACP 互联；SW1 分别与 SW2、SW3 使用四链路 LACP Trunk；爱快 AP 接入 SW1 <code>GE1/0/43</code> Trunk。</li><li><strong>网段</strong>：Office/RD 为 VLAN 10（<code>192.168.10.0/23</code>），IoT 为 VLAN 20（<code>192.168.20.0/23</code>），管理网为 VLAN 99（<code>192.168.99.0/24</code>）。</li><li><strong>策略出口</strong>：Arch Linux 旁路由（<code>192.168.10.62</code>）通过 Hysteria TProxy 处理非 CN、<code>rhzy.ai</code> 与远端私网的 TCP/UDP 策略路由；公网 <code>:443</code> 入站 DNAT 到后端时，经旁路由保持对称回程。</li></ul><h2 id="遵义互联" tabindex="-1">遵义互联 <a class="header-anchor" href="#遵义互联" aria-label="Permalink to &quot;遵义互联&quot;">​</a></h2><p>遵义侧使用 CCR1072（RouterOS 7.23.2），承载本地 WireGuard 与 LAN/OVPN 网段。两地通过 GRE 连接，公网端点已脱敏，隧道地址为 <code>172.16.1.2</code> 与 <code>172.16.1.3</code>。</p><h2 id="运维约束" tabindex="-1">运维约束 <a class="header-anchor" href="#运维约束" aria-label="Permalink to &quot;运维约束&quot;">​</a></h2><ol><li>VLAN 10、20、99 的端口成员、Trunk 的 tagged/native 设置和 LACP 对端必须与图表保持一致。</li><li>每次变更路由标记、NAT、Hysteria 或 GRE 配置后，应验证远端私网与公网入站的对称回程。</li><li>CCR、交换机、旁路由的配置备份与恢复步骤必须关联到变更记录，且不得提交密码、私钥或令牌。</li><li>GRE 当前按明文记录；若后续承载敏感业务流量，应评估叠加加密隧道及密钥轮换方案。</li></ol><p>下一步可补充机柜端口映射、AP 覆盖图、各 VLAN 的访问控制矩阵和故障切换演练记录。</p>',11)])])}const _=o(c,[["render",d]]);export{A as __pageData,_ as default};
